 11	public class Routes {
 12	    private static final Gson gson = new Gson();
 13	
 14	    public static void setup(Javalin app) {
 15	        app.post("/checkout/summary", Routes::checkoutSummary);
 16	        app.post("/orders", Routes::createOrder);
 17	        app.get("/orders/{id}", Routes::getOrder);
 18	        app.post("/orders/{id}/payment", Routes::processPayment);
 19	        app.post("/orders/{id}/shipment", Routes::shipOrder);
 20	        app.post("/orders/{id}/delivery", Routes::deliverOrder);
 21	        app.post("/orders/{id}/cancellation", Routes::cancelOrder);
 22	        app.get("/products/{sku}", Routes::getProduct);
 23	        app.get("/customers/{cpf}", Routes::getCustomer);
 24	        app.get("/customers/{cpf}/notifications", Routes::getNotifications);
 25	        app.post("/notifications/{id}/read", Routes::markNotificationAsRead);
 26	    }
 27	
 28	    private static void checkoutSummary(Context ctx) throws SQLException {
 29	        CheckoutRequest req = gson.fromJson(ctx.body(), CheckoutRequest.class);
 30	        CheckoutService.ValidationError validationError = CheckoutService.validateCheckoutRequest(req);
 31	
 32	        if (validationError != null) {
 33	            ctx.status(validationError.httpStatus);
 34	            ctx.json(new ErrorResponse(validationError.code));
 35	            return;
 36	        }
 37	
 38	        OrderSummary summary = CheckoutService.calculateSummary(req);
 39	        ctx.status(200);
 40	        ctx.json(summary);
 41	    }
 42	
 43	    private static void createOrder(Context ctx) throws SQLException {
 44	        CheckoutRequest req = gson.fromJson(ctx.body(), CheckoutRequest.class);
 45	        CheckoutService.ValidationError validationError = CheckoutService.validateCheckoutRequest(req);
 46	
 47	        if (validationError != null) {
 48	            ctx.status(validationError.httpStatus);
 49	            ctx.json(new ErrorResponse(validationError.code));
 50	            return;
 51	        }
 52	
 53	        OrderSummary summary = CheckoutService.calculateSummary(req);
 54	        Order order = OrderService.createOrder(req, summary);
 55	
 56	        ctx.status(201);
 57	        ctx.json(order);
 58	    }
 59	
 60	    private static void getOrder(Context ctx) throws SQLException {
 61	        String orderId = ctx.pathParam("id");
 62	        Order order = OrderService.getOrder(orderId);
 63	
 64	        if (order == null) {
 65	            ctx.status(404);
 66	            ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
 67	            return;
 68	        }
 69	
 70	        ctx.status(200);
 71	        ctx.json(order);
 72	    }
 73	
 74	    private static void processPayment(Context ctx) throws SQLException {
 75	        String orderId = ctx.pathParam("id");
 76	        PaymentRequest paymentReq = gson.fromJson(ctx.body(), PaymentRequest.class);
 77	
 78	        PaymentService.PaymentResult result = PaymentService.processPayment(orderId, paymentReq);
 79	
 80	        if (!result.success) {
 81	            ctx.status(result.httpStatus);
 82	            ctx.json(new ErrorResponse(result.error));
 83	            return;
 84	        }
 85	
 86	        ctx.status(200);
 87	        ctx.json(result.order);
 88	    }
 89	
 90	    private static void shipOrder(Context ctx) throws SQLException {
 91	        String orderId = ctx.pathParam("id");
 92	        ShipmentRequest shipmentReq = gson.fromJson(ctx.body(), ShipmentRequest.class);
 93	
 94	        Order order = OrderService.getOrder(orderId);
 95	        if (order == null) {
 96	            ctx.status(404);
 97	            ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
 98	            return;
 99	        }
100	
101	        if (shipmentReq.trackingCode == null || shipmentReq.trackingCode.isEmpty()) {
102	            ctx.status(422);
103	            ctx.json(new ErrorResponse("INVALID_ORDER"));
104	            return;
105	        }
106	
107	        if (order.status != Enums.OrderStatus.PAID) {
108	            ctx.status(409);
109	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
110	            return;
111	        }
112	
113	        OrderService.updateOrderTracking(orderId, shipmentReq.trackingCode);
114	        OrderService.updateOrderStatus(orderId, Enums.OrderStatus.SHIPPED);
115	
116	        String cpf = OrderService.getCustomerCpf(orderId);
117	        NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_SHIPPED, orderId);
118	
119	        ctx.status(200);
120	        ctx.json(OrderService.getOrder(orderId));
121	    }
122	
123	    private static void deliverOrder(Context ctx) throws SQLException {
124	        String orderId = ctx.pathParam("id");
125	        Order order = OrderService.getOrder(orderId);
126	
127	        if (order == null) {
128	            ctx.status(404);
129	            ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
130	            return;
131	        }
132	
133	        if (order.status != Enums.OrderStatus.SHIPPED) {
134	            ctx.status(409);
135	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
136	            return;
137	        }
138	
139	        OrderService.updateOrderStatus(orderId, Enums.OrderStatus.DELIVERED);
140	
141	        ctx.status(200);
142	        ctx.json(OrderService.getOrder(orderId));
143	    }
144	
145	    private static void cancelOrder(Context ctx) throws SQLException {
146	        String orderId = ctx.pathParam("id");
147	        Order order = OrderService.getOrder(orderId);
148	
149	        if (order == null) {
150	            ctx.status(404);
151	            ctx.json(new ErrorResponse("ORDER_NOT_FOUND"));
152	            return;
153	        }
154	
155	        if (order.status == Enums.OrderStatus.SHIPPED || order.status == Enums.OrderStatus.DELIVERED) {
156	            ctx.status(409);
157	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED"));
158	            return;
159	        }
160	
161	        String cpf = OrderService.getCustomerCpf(orderId);
162	
163	        if (order.status == Enums.OrderStatus.PAID) {
164	            for (OrderItem item : order.items) {
165	                ProductService.updateStock(item.sku, item.quantity);
166	            }
167	            CustomerService.updateCreditBalance(cpf, -order.summary.nextPurchaseCredit);
168	        }
169	
170	        OrderService.updateOrderStatus(orderId, Enums.OrderStatus.CANCELLED);
171	        NotificationService.createNotification(cpf, Enums.NotificationType.ORDER_CANCELLED, orderId);
172	
173	        ctx.status(200);
174	        ctx.json(OrderService.getOrder(orderId));
175	    }
