219	    private static void markNotificationAsRead(Context ctx) throws SQLException {
220	        String notificationId = ctx.pathParam("id");
221	        Notification notification = NotificationService.getNotification(notificationId);
222	
223	        if (notification == null) {
224	            ctx.status(404);
225	            ctx.json(new ErrorResponse("NOTIFICATION_NOT_FOUND"));
226	            return;
