283	import com.loja.api.Routes;
284	import com.loja.database.Database;
285	import io.javalin.Javalin;
286	import io.javalin.json.JsonMapper;
287	
288	import java.lang.reflect.Type;
289	
290	public class App {
291	    public static void main(String[] args) throws Exception {
292	        String dbUrl = System.getenv("DB_URL");
293	        String dbUser = System.getenv("DB_USER");
294	        String dbPassword = System.getenv("DB_PASSWORD");
295	        String port = System.getenv("PORT");
296	
297	        if (dbUrl == null || dbUrl.isEmpty()) {
298	            dbUrl = "jdbc:postgresql://localhost:5432/orderservice";
299	        }
300	        if (dbUser == null || dbUser.isEmpty()) {
301	            dbUser = "postgres";
302	        }
303	        if (dbPassword == null || dbPassword.isEmpty()) {
304	            dbPassword = "postgres";
305	        }
306	        if (port == null || port.isEmpty()) {
307	            port = "8080";
308	        }
309	
310	        Database.init(dbUrl, dbUser, dbPassword);
311	
312	        int portNum = Integer.parseInt(port);
313	
314	        Javalin app = Javalin.create(config -> {
315	            config.jsonMapper(new JsonMapper() {
316	                private final com.google.gson.Gson gson = new com.google.gson.Gson();
317	
318	                @Override
319	                public String toJsonString(Object obj, Type type) {
320	                    return gson.toJson(obj, type);
321	                }
322	
323	                @Override
324	                public Object fromJsonString(String json, Type targetType) {
325	                    return gson.fromJson(json, targetType);
326	                }
327	            });
328	        }).start(portNum);
329	
330	        Routes.setup(app);
331	
332	        System.out.println("Order service started on port " + portNum);
333	    }
334	}

