  1	package com.loja.services;
  2	
  3	import com.loja.api.CheckoutRequest;
  4	import com.loja.database.Database;
  5	import com.loja.models.*;
  6	import com.loja.utils.MoneyUtils;
  7	import java.sql.SQLException;
  8	import java.util.*;
  9	import java.util.regex.Pattern;
 10	
 11	public class CheckoutService {
 12	    private static final Pattern ZIP_CODE_PATTERN = Pattern.compile("^\\d{8}$");
 13	    private static final double MAX_COURIER_WEIGHT = 5.0;
 14	    private static final double MAX_DISCOUNT_PERCENTAGE = 0.30;
 15	    private static final long PAYMENT_TIMEOUT_MS = 48 * 60 * 60 * 1000;
 16	
 17	    public static ValidationError validateCheckoutRequest(CheckoutRequest req) throws SQLException {
 18	        if (req.items == null || req.items.isEmpty()) {
 19	            return new ValidationError("INVALID_ORDER", 422);
 20	        }
 21	
 22	        if (req.customer == null || req.customer.cpf == null || req.customer.cpf.isEmpty() ||
