323	    private static boolean hasCompletedOrder(String cpf) throws SQLException {
324	        String sql = "SELECT COUNT(*) as count FROM orders WHERE cpf = ? AND (status = 'PAID' OR status = 'SHIPPED' OR status = 'DELIVERED')";
325	        java.sql.Connection conn = Database.getDataSource().getConnection();
326	        java.sql.PreparedStatement pstmt = conn.prepareStatement(sql);
327	        pstmt.setString(1, cpf);
328	        java.sql.ResultSet rs = pstmt.executeQuery();
329	        rs.next();
330	        int count = rs.getInt("count");
331	        rs.close();
332	        pstmt.close();
333	        conn.close();
334	        return count > 0;
335	    }
