337	    private static ShippingInfo calculateShipping(CheckoutRequest req) throws SQLException {
338	        Enums.ShippingMethod method = Enums.ShippingMethod.valueOf(req.shippingMethod);
339	
340	        double totalWeight = 0;
341	        for (CheckoutRequest.OrderItemData item : req.items) {
342	            Product product = ProductService.getProduct(item.sku);
343	            totalWeight += product.weightKg * item.quantity;
344	        }
345	
346	        if (method == Enums.ShippingMethod.STORE_PICKUP) {
347	            return new ShippingInfo(0, 1);
348	        }
349	
350	        if (method == Enums.ShippingMethod.COURIER) {
351	            if (totalWeight > MAX_COURIER_WEIGHT) {
352	                return null;
353	            }
354	            return new ShippingInfo(18.0, 0);
355	        }
356	
357	        String translogUrl = System.getenv("TRANSLOG_URL");
358	        if (translogUrl == null || translogUrl.isEmpty()) {
359	            return null;
360	        }
361	
362	        String service = method == Enums.ShippingMethod.ECONOMY ? "STD" : "EXP";
363	        int weightGrams = (int) (totalWeight * 1000);
364	
365	        TranslogResponse response = queryTranslog(translogUrl, req.zipCode, weightGrams, service);
366	        if (response == null) {
367	            return null;
368	        }
369	
370	        if (response.error != null) {
371	            return null;
372	        }
373	
374	        double costReais = response.priceCents / 100.0;
375	        int daysBase = (int) Math.ceil(response.etaHours / 24.0);
376	
377	        Enums.Region region = Enums.Region.valueOf(req.region);
378	        int daysExtra = 0;
379	        if (region == Enums.Region.NORTH) {
380	            daysExtra = 3;
381	        } else if (region == Enums.Region.NORTHEAST) {
382	            daysExtra = 2;
383	        }
384	
385	        return new ShippingInfo(costReais, daysBase + daysExtra);
386	    }
