 11	    public static Order createOrder(CheckoutRequest req, OrderSummary summary) throws SQLException {
 12	        String orderId = UUID.randomUUID().toString();
 13	        Instant now = Instant.now();
 14	
 15	        CustomerService.getOrCreateCustomer(req.customer.cpf, req.customer.email);
 16	
 17	        String sql = """
 18	            INSERT INTO orders (id, cpf, email, status, created_at, products_subtotal, coupon_discount,
 19	                               shipping_cost, delivery_days, insurance, payment_adjustment, final_total,
 20	                               installments, installment_amount, next_purchase_credit, gift,
 21	                               region, shipping_method, payment_method, club_tier, coupon, paid_at, payment_transaction_id)
 22	            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL)
 23	            """;
 24	
 25	        try (Connection conn = Database.getDataSource().getConnection();
 26	             PreparedStatement pstmt = conn.prepareStatement(sql)) {
 27	            pstmt.setString(1, orderId);
 28	            pstmt.setString(2, req.customer.cpf);
 29	            pstmt.setString(3, req.customer.email);
 30	            pstmt.setString(4, Enums.OrderStatus.AWAITING_PAYMENT.name());
 31	            pstmt.setObject(5, now);
 32	            pstmt.setDouble(6, summary.productsSubtotal);
 33	            pstmt.setDouble(7, summary.couponDiscount);
 34	            pstmt.setDouble(8, summary.shippingCost);
 35	            pstmt.setInt(9, summary.deliveryDays);
 36	            pstmt.setDouble(10, summary.insurance);
 37	            pstmt.setDouble(11, summary.paymentAdjustment);
 38	            pstmt.setDouble(12, summary.finalTotal);
 39	            pstmt.setInt(13, summary.installments);
 40	            pstmt.setDouble(14, summary.installmentAmount);
 41	            pstmt.setDouble(15, summary.nextPurchaseCredit);
 42	            pstmt.setBoolean(16, summary.gift);
 43	            pstmt.setString(17, req.region);
 44	            pstmt.setString(18, req.shippingMethod);
 45	            pstmt.setString(19, req.paymentMethod);
 46	            pstmt.setString(20, req.clubTier);
 47	            pstmt.setString(21, req.coupon != null && !req.coupon.isEmpty() ? req.coupon : null);
 48	            pstmt.executeUpdate();
 49	        }
 50	
 51	        for (CheckoutRequest.OrderItemData item : req.items) {
 52	            String itemSql = "INSERT INTO order_items (order_id, sku, quantity) VALUES (?, ?, ?)";
 53	            try (Connection conn = Database.getDataSource().getConnection();
 54	                 PreparedStatement pstmt = conn.prepareStatement(itemSql)) {
 55	                pstmt.setString(1, orderId);
 56	                pstmt.setString(2, item.sku);
 57	                pstmt.setInt(3, item.quantity);
 58	                pstmt.executeUpdate();
 59	            }
 60	        }
 61	
 62	        return getOrder(orderId);
 63	    }
