115	                insertProduct(conn, "BON-001", "Boné aba reta", 59.90, 0.15, 0, false);
116	                insertProduct(conn, "REL-001", "Relógio digital", 129.90, 0.20, 8, true);
117	                conn.commit();
118	            }
119	            rs.close();
120	            pstmt.close();
121	        }
122	    }
