135	        pstmt.close();
136	    }
137	
138	    public static HikariDataSource getDataSource() {
139	        return dataSource;
140	    }
141	
142	    public static void close() {
143	        if (dataSource != null) {
144	            dataSource.close();
145	        }
146	    }
147	}
